import fs from 'node:fs';

export function parseEnv(text) {
  const env = {};
  for (let line of text.replace(/^﻿/, '').split(/\r?\n/)) {
    line = line.trim();
    if (!line || line.startsWith('#')) continue;
    const m = line.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!m) continue;
    let v = m[2].trim();
    if (/^(["']).*\1$/.test(v)) v = v.slice(1, -1);
    env[m[1]] = v;
  }
  return env;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  let fileEnv = {};
  try { fileEnv = parseEnv(fs.readFileSync('.env', 'utf8')); } catch {}
  const key = process.env.GEMINI_API_KEY || fileEnv.GEMINI_API_KEY;
  if (!key) { console.error('Error: GEMINI_API_KEY is missing'); process.exit(1); }
}

